import React, { useState, useEffect, useMemo, useRef } from 'react'
import AdaptableCard from 'components/shared/AdaptableCard'
import DataTable from 'components/shared/DataTable'
import Tabs from 'components/ui/Tabs'
import debounce from 'lodash/debounce'
import Button from 'components/ui/Buttons'
import Input from 'components/ui/Input'
import toast from 'components/ui/toast'
import Notification from 'components/ui/Notification'
import { Link, useNavigate } from 'react-router-dom'
import { MdCreate, MdAdd, MdDelete, MdImportExport } from 'react-icons/md'
import { HiSearch } from 'react-icons/hi'
import { apiVendorPaymentGet } from 'services/VendorPaymentService'
import NumberFormat from 'react-number-format'
import Moment from 'react-moment'

const { TabNav, TabList, TabContent } = Tabs

const VendorPayment = () => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(true)
    const [tableData, setTableData] = useState({
        total: 0,
        pageIndex: 1,
        pageSize: 10,
        query: '',
        sort: {
            order: '',
            key: '',
        },
        status: 'pending',
    })

    const [statusCount, setStatusCount] = useState({
        immediate: 0,
        due: 0,
        notDue: 0,
        pending: 0,
        approved: 0,
        rejected: 0,
        inActive: 0,
    })

    const tabChanges = (tab) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ status: tab },
        }))
    }

    const navigate = useNavigate()
    const inputRef = useRef(null)

    const debounceFn = debounce(handleDebounceFn, 1000)

    function handleDebounceFn(val) {
        if (typeof val === 'string' && (val.length > 1 || val.length === 0)) {
            setTableData((prevData) => ({
                ...prevData,
                ...{ query: val, pageIndex: 1 },
            }))
        }
    }

    const handleChange = (e) => {
        debounceFn(e.target.value)
    }

    const handleRowClick = (data) => {
        console.log(data)
        if (data.transaction_date) {
            console.log(data.id)
            navigate(
                `/transaction/vendor-payment/approved-vendor-payment/${data.id}`
            )
        } else {
            console.log(data.id)
            navigate(
                `/transaction/vendor-payment/edit-vendor-payment/${data.id}`
            )
        }
    }

    const columns = useMemo(
        () => [
            {
                header: 'Sr. No.',
                cell: (props) => props.row.index + 1,
                width: 60,
            },
            {
                header:
                    tableData.status == 'immediate' ||
                    tableData.status == 'due' ||
                    tableData.status == 'notDue'
                        ? 'Due Date'
                        : 'Date Of Transaction',
                accessorKey: 'transaction_date',
                cell: (props) =>
                    tableData.status == 'immediate' ||
                    tableData.status == 'due' ||
                    tableData.status == 'notDue' ? (
                        <Moment format="DD-MM-YYYY">
                            {props.row.original.date_of_processing}
                        </Moment>
                    ) : (
                        <Moment format="DD-MM-YYYY">
                            {props.row.original.transaction_date}
                        </Moment>
                    ),
                width: 110,
            },
            {
                header: 'Invoice No',
                accessorKey: 'invoice_no',
                cell: (props) => {
                    return props.row.original.invoice_no == null
                        ? ''
                        : props.row.original.invoice_no
                },
                width: 150,
            },
            {
                header: 'Vendors',
                accessorKey: 'vendor_names',
                cell: (props) => {
                    return props.row.original.vendor_names
                        ? props.row.original.vendor_names
                        : props.row.original.vendor_name
                },
                width: 450,
            },
            {
                header: 'Total Amount',
                accessorKey: 'total_amount',
                cell: (props) => (
                    <NumberFormat
                        displayType="text"
                        prefix={'₹'}
                        thousandsGroupStyle={'lakh'}
                        decimalScale={2}
                        value={
                            props.row.original.total_amount
                                ? props.row.original.total_amount
                                : props.row.original.final_amount
                        }
                        allowLeadingZeros
                        thousandSeparator=","
                    />
                ),
                width: 100,
            },
            {
                header: 'Action',
                width: 60,
                cell: (props) => (
                    <>
                        <Button
                            shape="circle"
                            size="sm"
                            variant="twoTone"
                            icon={<MdCreate />}
                            className="mr-3"
                            onClick={() => {
                                handleRowClick(props.row.original)
                            }}
                        />
                    </>
                ),
            },
        ],
        [tableData]
    )

    const handlePaginationChange = (pageIndex) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageIndex } }))
    }

    const handleSelectChange = (pageSize) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageSize } }))
    }

    const handleSort = ({ order, key }) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ sort: { order, key } },
        }))
    }

    console.log('Vendor Payments Loading....')

    useEffect(() => {
        const fetchData = async () => {
            // setLoading(true)
            await apiVendorPaymentGet(tableData)
                .then((data) => {
                    console.log(data)
                    if (data.data) {
                        setStatusCount(data.data['statusCount'])
                        setData(data.data['rows'])
                        setTableData((prevData) => ({
                            ...prevData,
                            ...{ total: data.data['total'] },
                        }))
                        setLoading(false)
                    }
                })
                .catch((error) => {
                    if (error.response.status === 500) {
                        console.log(error)
                        setLoading(false)
                    }
                })
            return true
        }
        fetchData()
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        tableData.pageIndex,
        tableData.sort,
        tableData.pageSize,
        tableData.query,
        tableData.status,
    ])

    return (
        <AdaptableCard className="card-shadow">
            <div className="lg:flex items-center justify-between mb-0">
                <h3 className="mb-0 lg:mb-0 ">Vendor Payment</h3>
                <div className="flex flex-row lg:flex-row lg:items-center">
                    <Input
                        ref={inputRef}
                        placeholder="Search..."
                        size="sm"
                        className="lg:w-52 mr-4"
                        onChange={handleChange}
                        prefix={<HiSearch className="text-lg" />}
                    />
                    <Link
                        to={'/transaction/vendor-payment/add-vendor-payment'}
                        className=" mr-4 inline-flex"
                    >
                        <Button size="sm" variant="solid" icon={<MdAdd />}>
                            <span>Add Vendor Payment</span>
                        </Button>
                    </Link>
                </div>
            </div>

            <Tabs
                defaultValue="pending"
                onChange={(tabValue) => {
                    tabChanges(tabValue)
                }}
            >
                <TabList className="justify-between">
                    <div className="flex justify-start">
                        <TabNav value="immediate">
                            Immediate {`(${statusCount.immediate})`}
                        </TabNav>
                        <TabNav value="due">
                            Due {`(${statusCount.due})`}
                        </TabNav>
                        <TabNav value="notDue">
                            Not Due {`(${statusCount.notDue})`}
                        </TabNav>
                    </div>
                    <div className="flex justify-end">
                        <TabNav value="pending">
                            Pending Approval {`(${statusCount.pending})`}
                        </TabNav>
                        <TabNav value="rejected">
                            Rejected {`(${statusCount.rejected})`}
                        </TabNav>
                        <TabNav value="inactive">
                            Inactive {`(${statusCount.inActive})`}
                        </TabNav>
                        <TabNav value="approved">
                            Approved {`(${statusCount.approved})`}
                        </TabNav>
                    </div>
                </TabList>
                <div className="p-1">
                    <TabContent value="immediate"></TabContent>
                    <TabContent value="due"></TabContent>
                    <TabContent value="notDue"></TabContent>
                    <TabContent value="pending"></TabContent>
                    <TabContent value="rejected"></TabContent>
                    <TabContent value="inactive"></TabContent>
                    <TabContent value="approved"></TabContent>
                </div>
            </Tabs>
            <DataTable
                columns={columns}
                data={data}
                loading={loading}
                pagingData={tableData}
                onPaginationChange={handlePaginationChange}
                onSelectChange={handleSelectChange}
                onSort={handleSort}
            />
        </AdaptableCard>
    )
}

export default VendorPayment
